+<?php
+require_once 'includes/admin_auth.php';
+
+$adminAuth = new AdminAuth();
+$currentAdmin = $adminAuth->requireAuth();
+
+$message = '';
+$messageType = '';
+$scannedStudent = null;
+$events = [];
+$selectedEventId = null;
+
+// Load active events for selection (only today's events)
+try {
+    $database = new Database();
+    $db = $database->getConnection();
+    
+    // Get today's date
+    $today = date('Y-m-d');
+    
+    // Query to get only today's active events
+    $stmtEvents = $db->prepare("
+        SELECT id, event_name, event_date, event_time 
+        FROM events 
+        WHERE is_active = 1 
+        AND event_date = :today
+        ORDER BY event_time ASC
+    ");
+    $stmtEvents->execute([':today' => $today]);
+    $events = $stmtEvents->fetchAll(PDO::FETCH_ASSOC);
+    
+    if ($events) {
+        $selectedEventId = isset($_POST['event_id']) ? (int)$_POST['event_id'] : (int)$events[0]['id'];
+    }
+} catch (Exception $e) {
+    // ignore
+}
+
+// Handle QR code scan result
+if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['qr_data'])) {
+    $qrData = trim($_POST['qr_data']);
+    $eventIdParam = isset($_POST['event_id']) ? (int)$_POST['event_id'] : ($selectedEventId ?? null);
+    
+    try {
+        if (!isset($db)) {
+            $database = new Database();
+            $db = $database->getConnection();
+        }
+        
+        // Extract student ID from QR data (assuming QR contains student_id)
+        $studentId = $qrData;
+        
+        // Get student data
+        $stmt = $db->prepare("SELECT * FROM students WHERE student_id = ? OR qr_code = ?");
+        $stmt->execute([$studentId, $qrData]);
+        $scannedStudent = $stmt->fetch(PDO::FETCH_ASSOC);
+        
+        if ($scannedStudent) {
+            // If an event is selected, upsert attendance with current timestamp as Time In
+            if ($eventIdParam) {
+                // Ensure row exists
+                $db->prepare("INSERT IGNORE INTO attendance (student_id, event_id, qr_code_used, status) VALUES (?, ?, ?, 'present')")
+                   ->execute([$scannedStudent['id'], $eventIdParam, $qrData]);
+
+                // Fetch existing times
+                $times = $db->prepare("SELECT time_in, time_out, time_in_2, time_out_2 FROM attendance WHERE student_id = ? AND event_id = ?");
+                $times->execute([$scannedStudent['id'], $eventIdParam]);
+                $t = $times->fetch(PDO::FETCH_ASSOC);
+
+                if (empty($t['time_in'])) {
+                    $db->prepare("UPDATE attendance SET time_in = NOW(), status='present', qr_code_used=? WHERE student_id=? AND event_id=?")
+                       ->execute([$qrData, $scannedStudent['id'], $eventIdParam]);
+                } elseif (empty($t['time_out'])) {
+                    $db->prepare("UPDATE attendance SET time_out = NOW(), qr_code_used=? WHERE student_id=? AND event_id=?")
+                       ->execute([$qrData, $scannedStudent['id'], $eventIdParam]);
+                } elseif (empty($t['time_in_2'])) {
+                    $db->prepare("UPDATE attendance SET time_in_2 = NOW(), qr_code_used=? WHERE student_id=? AND event_id=?")
+                       ->execute([$qrData, $scannedStudent['id'], $eventIdParam]);
+                } elseif (empty($t['time_out_2'])) {
+                    $db->prepare("UPDATE attendance SET time_out_2 = NOW(), qr_code_used=? WHERE student_id=? AND event_id=?")
+                       ->execute([$qrData, $scannedStudent['id'], $eventIdParam]);
+                } else {
+                    // Optional: overwrite last time_out_2 to reflect latest scan
+                    $db->prepare("UPDATE attendance SET time_out_2 = NOW(), qr_code_used=? WHERE student_id=? AND event_id=?")
+                       ->execute([$qrData, $scannedStudent['id'], $eventIdParam]);
+                }
+            }
+            $message = 'Student data retrieved successfully!';
+            $messageType = 'success';
+        } else {
+            $message = 'Student not found with the scanned QR code';
+            $messageType = 'error';
+        }
+        
+    } catch (Exception $e) {
+        $message = 'Error: ' . $e->getMessage();
+        $messageType = 'error';
+    }
+}
